import { rootTileAt } from './worldGrid';

// Coordinate → administrative place lookup from static chunks generated by scripts/places.mjs.
export type PlaceIndex = {
  v: 1;
  country: string;
  cells: number;
  year: number;
  source: string;
  source_url: string;
  license: string;
  bbox: [number, number, number, number];
  provinces: [code: string, ko: string, en: string][];
  districts: [code: string, ko: string, en: string][];
  areas: [code: string, ko: string, en: string, longitude: number, latitude: number][];
  roots: string[];
};
export type PlaceChunk = { v: 1; rows: number[][] };
export type Place = {
  code: string;
  area: { ko: string; en: string };
  district: { ko: string; en: string };
  province: { ko: string; en: string };
  point: [number, number];
};

export const placeDatasets = [
  { country: 'KOR', path: '/places/kor', bbox: [124.5, 33, 132, 38.7] as const },
];
export const placeDatasetAt = (longitude: number, latitude: number) =>
  placeDatasets.find(
    ({ bbox: [w, s, e, n] }) => longitude >= w && longitude <= e && latitude >= s && latitude <= n,
  );
// The root key ("x:y") and the cell inside that root's chunk for a coordinate.
export function placeCell(longitude: number, latitude: number, cells: number) {
  const tile = rootTileAt(longitude, latitude);
  const [, x, y] = tile.id.split(':');
  return {
    root: `${x}:${y}`,
    column: Math.min(
      cells - 1,
      Math.floor(((longitude - tile.west) / (tile.east - tile.west)) * cells),
    ),
    row: Math.min(
      cells - 1,
      Math.floor(((tile.north - latitude) / (tile.north - tile.south)) * cells),
    ),
  };
}
export function chunkValue(chunk: PlaceChunk, row: number, column: number) {
  const runs = chunk.rows[row];
  for (let i = 0, c = 0; i < runs.length; i += 2) {
    c += runs[i + 1];
    if (column < c) return runs[i];
  }
  return -1;
}
export function placeFromIndex(index: PlaceIndex, area: number): Place | null {
  const entry = index.areas[area];
  if (!entry) return null;
  const [code, ko, en, longitude, latitude] = entry;
  const find = (list: PlaceIndex['districts'], prefix: string) => {
    const match = list.find((item) => item[0] === prefix);
    return { ko: match?.[1] ?? '', en: match?.[2] ?? '' };
  };
  return {
    code,
    area: { ko, en },
    district: find(index.districts, code.slice(0, 5)),
    province: find(index.provinces, code.slice(0, 2)),
    point: [longitude, latitude],
  };
}
export function placeName(place: Place, locale: string, short = false) {
  if (locale === 'ko')
    return (
      short
        ? [place.district.ko, place.area.ko]
        : [place.province.ko, place.district.ko, place.area.ko]
    )
      .filter(Boolean)
      .join(' ');
  return (
    short
      ? [place.area.en, place.district.en]
      : [place.area.en, place.district.en, place.province.en]
  )
    .filter(Boolean)
    .join(', ');
}
export function searchPlaces(index: PlaceIndex, query: string, limit = 16): Place[] {
  const text = query.trim().toLocaleLowerCase().replace(/\s+/g, ' ');
  if (!text) return [];
  const results: Place[] = [];
  for (let i = 0; i < index.areas.length && results.length < limit; i++) {
    const place = placeFromIndex(index, i);
    if (
      place &&
      [placeName(place, 'ko'), placeName(place, 'en')].some((name) =>
        name.toLocaleLowerCase().includes(text),
      )
    )
      results.push(place);
  }
  return results;
}
